const SCHEMA = {"type": "object", "additionalProperties": false, "required": ["category", "subcat", "dir", "proposals"], "properties": {"category": {"type": "string"}, "subcat": {"type": "string"}, "dir": {"type": "string"}, "proposals": {"type": "array", "items": {"type": "object", "additionalProperties": false, "required": ["slug", "title", "keyword", "angle", "competition"], "properties": {"slug": {"type": "string"}, "title": {"type": "string"}, "keyword": {"type": "string"}, "angle": {"type": "string"}, "competition": {"type": "string", "enum": ["low", "medium"]}}}}}};
phase('Propose')
log(`Long-tail proposals across ${JOBS.length} buckets`)
const CONC = 8;
const results = [];
for (let i = 0; i < JOBS.length; i += CONC) {
  const chunk = JOBS.slice(i, i + CONC);
  const part = await parallel(chunk.map(j => () =>
    agent(PREAMBLE + j.tail, { label: j.label, phase: 'Propose', schema: SCHEMA, model: 'sonnet' })
      .then(r => r ? { cat: j.cat, sub: j.sub, dir: j.dir, proposals: r.proposals || [] } : null)));
  results.push(...part);
  log(`proposed ${results.filter(Boolean).length}/${JOBS.length} buckets`);
}
const ok = results.filter(Boolean)
const total = ok.reduce((n, r) => n + r.proposals.length, 0)
log(`Got ${total} raw long-tail proposals from ${ok.length}/${JOBS.length} buckets`)
return { buckets: ok, totalProposals: total }